package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n int64
	var k int64
	fmt.Fscan(reader, &n, &k)

	// The problem is equivalent to generating the k-th permutation in the list of all permutations that are fixed under the described operation.
	// These permutations are exactly those where every cycle in the standard cyclic representation is a singleton.
	// This means the permutation must be the identity permutation. However, this is not the case as per the sample inputs.

	// Re-analyzing the problem:
	// A permutation is fixed if, when converted to its standard cyclic representation and then the parentheses are removed, it remains the same.
	// This happens if and only if each cycle in the standard representation is of length 1 (i.e., the permutation is the identity) or the cycles are arranged such that removing parentheses doesn't change the permutation.

	// Actually, the fixed permutations are those where each cycle in the standard form, when written out, matches the original permutation.
	// This occurs when the permutation is a product of disjoint transpositions (cycles of length 2) and fixed points, arranged in a specific way.

	// The correct approach is to recognize that the fixed permutations are those that can be written as a product of disjoint cycles where each cycle is either a fixed point or a transposition (a, b) with a < b, and the cycles are ordered by their first element.

	// The number of such permutations is the number of involutions (permutations that are their own inverse) on n elements.
	// An involution is a permutation that is a product of disjoint transpositions and fixed points.

	// To generate the k-th involution in lexicographic order:
	// We can use a recursive approach, deciding for each position whether to fix it or pair it with a later position.

	// However, given the constraints (n up to 50 and k up to 1e18), we need an efficient way to count and generate.

	// The number of involutions on n elements is given by the recurrence:
	// I(n) = I(n-1) + (n-1)*I(n-2)
	// with I(0) = 1, I(1) = 1.

	// To generate the k-th involution in lexicographic order:
	// We build the permutation from left to right.
	// For each position i (1-indexed), we decide whether to:
	// 1. Fix i (i.e., p[i] = i), which contributes I(n-i) involutions.
	// 2. Pair i with some j > i (i.e., p[i] = j and p[j] = i), which contributes I(n-i-1) involutions for each valid j.

	// We need to precompute the number of involutions for all n up to 50.

	// Precompute involution counts
	maxN := 50
	invCount := make([]int64, maxN+1)
	invCount[0] = 1
	if maxN >= 1 {
		invCount[1] = 1
	}
	for i := 2; i <= maxN; i++ {
		invCount[i] = invCount[i-1] + int64(i-1)*invCount[i-2]
	}

	// Now generate the k-th involution (1-indexed)
	k-- // convert to 0-indexed

	perm := make([]int, n)
	used := make([]bool, n+1) // 1-indexed

	for i := int64(1); i <= n; i++ {
		if used[i] {
			continue
		}

		// Option 1: Fix i
		countFix := invCount[n-i]
		if k < countFix {
			perm[i-1] = int(i)
			used[i] = true
			continue
		}
		k -= countFix

		// Option 2: Pair i with some j > i
		for j := i + 1; j <= n; j++ {
			if used[j] {
				continue
			}
			countPair := invCount[n-i-1]
			if k < countPair {
				perm[i-1] = int(j)
				perm[j-1] = int(i)
				used[i] = true
				used[j] = true
				break
			}
			k -= countPair
		}
	}

	// Output the permutation
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	for i := 0; i < int(n); i++ {
		if i > 0 {
			fmt.Fprint(writer, " ")
		}
		fmt.Fprint(writer, perm[i])
	}
	fmt.Fprintln(writer)
}
