import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	var k uint64
	fmt.Fscan(in, &n, &k)

	// Generate all valid permutations of length n in lex order, pick k-th
	// Valid permutations are those that are fixed under the cycle-removal operation.
	// Observation: A permutation is fixed iff it is an involution (its own inverse).
	// Because the standard cycle representation of an involution, when parentheses removed,
	// gives back the same permutation.
	// Proof sketch: In an involution, every cycle has length 1 or 2.
	// For length 1: (a) -> a.
	// For length 2: (ab) with a > b becomes (a b) -> a b.
	// Reordering cycles by first element (which is the max) and concatenating gives the same permutation.
	// Conversely, if a permutation is fixed, it must be an involution.

	// So we need to generate the k-th involution of length n in lexicographic order.

	// We'll generate involutions recursively with pruning using counts.
	// Count[i] = number of involutions of length i
	// Count[0] = 1, Count[1] = 1, Count[i] = Count[i-1] + (i-1)*Count[i-2]

	count := make([]uint64, n+1)
	count[0] = 1
	if n >= 1 {
		count[1] = 1
	}
	for i := 2; i <= n; i++ {
		count[i] = count[i-1] + uint64(i-1)*count[i-2]
	}

	perm := make([]int, n)
	used := make([]bool, n+1) // 1-indexed

	var gen func(pos int, k uint64) bool
	gen = func(pos int, k uint64) bool {
		if pos > n {
			return k == 1
		}
		// Try placing the smallest available number at position pos
		for num := 1; num <= n; num++ {
			if used[num] {
				continue
			}
			// Option 1: num is a fixed point (cycle of length 1)
			if count[n-pos] >= k {
				perm[pos-1] = num
				used[num] = true
				if gen(pos+1, k) {
					return true
				}
				used[num] = false
			} else {
				k -= count[n-pos]
			}

			// Option 2: num pairs with some larger available number (cycle of length 2)
			// We need to choose a partner > num to maintain lex order
			for partner := num + 1; partner <= n; partner++ {
				if used[partner] {
					continue
				}
				c := count[n-pos-1]
				if c >= k {
					perm[pos-1] = num
					perm[pos] = partner
