	fmt.Fscan(in, &n, &k)
	k--
	p := make([]int, n+1)
	for i := 1; i <= n; i++ {
		p[i] = i
	}
	for i := 1; i <= n; i++ {
		if k == 0 {
			break
		}
		cnt := count(i + 1)
		if k >= cnt {
			k -= cnt
			continue
		}
		for j := i + 1; j <= n; j++ {
			if k < count(j) {
				p[i], p[j] = p[j], p[i]
				break
			}
			k -= count(j)
		}
	}
	for i := 1; i <= n; i++ {
		fmt.Printf("%d ", p[i])
	}
	fmt.Println()
}

func count(x int) int64 {
	if x > n {
		return 1
	}
	return int64(x) * count(x+1)
}
