var n int
var k int64
var cnt int64
var ans []int

func main() {
	in := bufio.NewReader(os.Stdin)
	fmt.Fscan(in, &n, &k)
	ans = make([]int, n)
	cnt = 0
	dfs(1)
	for i := 0; i < n; i++ {
		fmt.Printf("%d ", ans[i])
	}
	fmt.Println()
}

func dfs(pos int) {
	if cnt >= k {
		return
	}
	if pos > n {
		cnt++
		if cnt == k {
			for i := 0; i < n; i++ {
				ans[i] = ans[i]
			}
		}
		return
	}
	for i := pos; i <= n; i++ {
		if cnt >= k {
			return
		}
		swap(pos, i)
		dfs(pos + 1)
		swap(pos, i)
	}
}

func swap(a, b int) {
	ans[a-1], ans[b-1] = ans[b-1], ans[a-1]
}
